import React, { useState } from 'react';
import { Button } from './components/ui/button';
import { Card, CardContent } from './components/ui/card';

export default function FoodDonationApp() {
  const [userType, setUserType] = useState(null);
  const [donations, setDonations] = useState([]);
  const [newDonation, setNewDonation] = useState({ item: '', quantity: '' });

  const foodItems = [
    'Bread',
    'Rice',
    'Pasta',
    'Vegetables',
    'Fruits',
    'Dairy Products',
    'Meat',
    'Seafood',
    'Snacks',
    'Beverages'
  ];

  const handleDonationSubmit = () => {
    if (newDonation.item && newDonation.quantity) {
      setDonations([...donations, newDonation]);
      setNewDonation({ item: '', quantity: '' });
    }
  };

  const handleClaimDonation = (index) => {
    const updatedDonations = donations.filter((_, i) => i !== index);
    setDonations(updatedDonations);
  };

  if (!userType) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', minHeight: '100vh', padding: '20px' }}>
        <h1 style={{ fontSize: '2rem', fontWeight: 'bold', marginBottom: '20px' }}>Welcome to Food Donation App</h1>
        <Button onClick={() => setUserType('donor')}>Login as Donor</Button>
        <Button onClick={() => setUserType('ngo')} style={{ marginTop: '10px' }}>Login as NGO</Button>
      </div>
    );
  }

  return (
    <div style={{ padding: '20px' }}>
      <h1 style={{ fontSize: '1.5rem', fontWeight: 'bold', marginBottom: '20px' }}>{userType === 'donor' ? 'Post a Donation' : 'Available Donations'}</h1>

      {userType === 'donor' ? (
        <div style={{ marginBottom: '20px' }}>
          <select
            value={newDonation.item}
            onChange={(e) => setNewDonation({ ...newDonation, item: e.target.value })}
            style={{ border: '1px solid #ddd', padding: '10px', borderRadius: '5px', marginBottom: '10px', width: '100%' }}
          >
            <option value="">Select Food Item</option>
            {foodItems.map((item, index) => (
              <option key={index} value={item}>{item}</option>
            ))}
          </select>

          <input
            type="text"
            placeholder="Quantity"
            value={newDonation.quantity}
            onChange={(e) => setNewDonation({ ...newDonation, quantity: e.target.value })}
            style={{ border: '1px solid #ddd', padding: '10px', borderRadius: '5px', marginBottom: '10px', width: '100%' }}
          />

          <Button onClick={handleDonationSubmit}>Submit Donation</Button>
        </div>
      ) : (
        <div>
          {donations.length > 0 ? (
            donations.map((donation, index) => (
              <Card key={index} style={{ marginBottom: '20px' }}>
                <CardContent>
                  <h2 style={{ fontSize: '1.25rem', fontWeight: '600' }}>{donation.item}</h2>
                  <p>Quantity: {donation.quantity}</p>
                  <Button onClick={() => handleClaimDonation(index)} style={{ marginTop: '10px' }}>Claim Donation</Button>
                </CardContent>
              </Card>
            ))
          ) : (
            <p>No donations available at the moment.</p>
          )}
        </div>
      )}

      <Button onClick={() => setUserType(null)} style={{ marginTop: '20px' }}>Logout</Button>
    </div>
  );
}
